<!doctype html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1">
    <title><?= esc($pageTitle) ?> · Daymark</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap" rel="stylesheet">
    <style>
        :root{--ink:#20241f;--muted:#777c73;--paper:#f8f8f5;--white:#fff;--line:#e9e9e2;--green:#426548;--green-soft:#edf3eb;--orange:#d67a45;--shadow:0 18px 55px rgba(37,46,35,.07)}
        *{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:'DM Sans',sans-serif;font-size:15px;line-height:1.55}a{color:inherit;text-decoration:none}.shell{min-height:100vh;max-width:1440px;margin:auto;display:grid;grid-template-columns:252px minmax(0,1fr)}
        .sidebar{background:#fff;border-right:1px solid var(--line);padding:30px 20px;display:flex;flex-direction:column}.brand{display:flex;gap:12px;align-items:center;padding:0 10px 42px}.brand-mark{height:40px;width:40px;border-radius:13px;background:var(--green);color:white;display:grid;place-items:center;font-family:Manrope;font-size:19px;font-weight:800}.brand-name{font:800 19px Manrope;letter-spacing:-.7px}.brand-caption{font-size:11px;color:var(--muted);margin-top:1px}.nav-label{padding:0 12px;color:#a0a399;font-weight:700;font-size:10px;text-transform:uppercase;letter-spacing:1.25px;margin:0 0 10px}.nav{display:grid;gap:5px}.nav a{display:flex;align-items:center;gap:13px;padding:11px 13px;border-radius:10px;color:#75796f;font-weight:600;transition:.2s}.nav a:hover{background:#f6f7f3;color:var(--ink)}.nav a.active{background:var(--green-soft);color:var(--green)}.nav-icon{width:19px;text-align:center;font-size:17px}.sidebar-bottom{margin-top:auto;padding:16px 12px 0;border-top:1px solid var(--line);color:var(--muted);font-size:12px}.sidebar-bottom strong{display:block;color:var(--ink);font-size:13px;margin-bottom:2px}
        .main{min-width:0;padding:30px 48px 60px}.topbar{height:42px;display:flex;align-items:center;justify-content:space-between;margin-bottom:47px}.crumb{color:var(--muted);font-size:13px}.crumb b{color:var(--ink);font-weight:600}.today-pill{border:1px solid var(--line);background:white;border-radius:999px;padding:8px 13px;font-size:12px;color:var(--muted);display:flex;align-items:center;gap:8px}.today-dot{height:7px;width:7px;background:#7ca36e;border-radius:50%}.content{max-width:920px;margin:auto}.eyebrow{font-size:11px;letter-spacing:1.6px;text-transform:uppercase;color:var(--green);font-weight:700;margin:0 0 11px}.page-heading{font:800 clamp(30px,4vw,42px)/1.12 Manrope;letter-spacing:-1.7px;margin:0}.subtitle{color:var(--muted);margin:11px 0 0;font-size:15px}.heading-row{display:flex;align-items:flex-end;justify-content:space-between;gap:20px;margin-bottom:30px}.count-label{color:var(--muted);font-size:13px;padding-bottom:4px}.card{background:var(--white);border:1px solid var(--line);border-radius:17px;box-shadow:var(--shadow)}.task-list{overflow:hidden}.task-row{padding:17px 21px;display:grid;grid-template-columns:22px minmax(0,1fr) auto;gap:14px;align-items:center;border-bottom:1px solid #f0f0eb}.task-row:last-child{border-bottom:0}.check{height:19px;width:19px;border:1.5px solid #d8dacf;border-radius:6px;display:grid;place-items:center;font-size:12px;color:white}.check.done{background:var(--green);border-color:var(--green)}.task-title{font-weight:600;font-size:14px;line-height:1.4}.task-date{color:var(--muted);font-size:12px;margin-top:3px}.status{font-size:11px;font-weight:700;text-transform:capitalize;padding:5px 10px;border-radius:999px;white-space:nowrap}.status-pending{background:#f3f2ec;color:#777668}.status-completed{background:#edf4eb;color:#52764e}.status-in-progress{background:#fff1e7;color:#bc7040}.empty{padding:56px 24px;text-align:center}.empty-icon{font-size:30px;margin-bottom:9px}.empty h2{font:700 18px Manrope;margin:0 0 5px}.empty p{color:var(--muted);margin:0;font-size:13px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-bottom:22px}.stat{padding:17px 19px}.stat-label{font-size:12px;color:var(--muted)}.stat-value{font:800 25px Manrope;margin-top:3px;letter-spacing:-.7px}.section-title{font:700 17px Manrope;margin:0 0 14px}.profile-card{padding:28px;display:flex;align-items:center;gap:20px;margin-bottom:18px}.avatar{width:72px;height:72px;flex:none;border-radius:23px;background:var(--green-soft);color:var(--green);display:grid;place-items:center;font:800 27px Manrope}.profile-name{font:800 23px Manrope;letter-spacing:-.6px}.profile-handle{color:var(--muted);font-size:13px;margin-top:2px}.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.detail{padding:18px 20px}.detail-label{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:var(--muted);font-weight:700}.detail-value{margin-top:7px;font-weight:600;overflow-wrap:anywhere}.about-card{padding:30px}.about-card h2{font:700 20px Manrope;margin:0 0 10px}.about-card p{color:#686d64;margin:0;max-width:680px}.about-note{border-top:1px solid var(--line);margin-top:25px;padding-top:18px;color:var(--muted);font-size:13px}.about-note strong{color:var(--ink)}.footer{max-width:920px;margin:44px auto 0;color:#a0a399;font-size:11px}
        .add-card{padding:18px;margin-bottom:22px}.add-form{display:flex;gap:10px;align-items:center}.add-form input{font:inherit;border:1px solid var(--line);border-radius:9px;background:#fff;padding:11px 12px;min-width:0;color:var(--ink);outline:none}.add-form input:focus{border-color:#7b987d;box-shadow:0 0 0 3px rgba(66,101,72,.1)}.add-form .title-input{flex:1}.add-form input[type=date]{color:var(--muted);font-size:13px}.primary-button{border:0;border-radius:9px;background:var(--green);color:#fff;font:600 13px 'DM Sans',sans-serif;padding:11px 15px;cursor:pointer;white-space:nowrap;transition:.18s}.primary-button:hover{background:#34523a;transform:translateY(-1px)}.task-row.with-actions{grid-template-columns:22px minmax(0,1fr) auto auto}.task-actions{display:flex;gap:7px;align-items:center}.action-button{border:1px solid var(--line);background:#fff;color:#63705f;border-radius:8px;padding:6px 9px;font:600 11px 'DM Sans',sans-serif;cursor:pointer;white-space:nowrap}.action-button:hover{border-color:#a8b6a5;background:#f7faf6}.action-button.delete{color:#a36554}.action-button.delete:hover{border-color:#e2c4bb;background:#fff8f6}.notice{padding:11px 14px;border-radius:10px;margin:0 0 17px;font-size:13px}.notice.success{background:#edf4eb;color:#456b43}.notice.error{background:#fff0ed;color:#a44d3b}.field-error{font-size:12px;color:#a44d3b;margin:7px 0 0 3px}
        @media(max-width:900px){.shell{grid-template-columns:215px minmax(0,1fr)}.main{padding:26px 28px 50px}.topbar{margin-bottom:36px}.sidebar{padding:26px 15px}}
        @media(max-width:760px){.add-form{flex-wrap:wrap}.add-form .title-input{flex-basis:100%}.task-row.with-actions{grid-template-columns:22px minmax(0,1fr)}.task-row.with-actions .status{grid-column:2}.task-row.with-actions .task-actions{grid-column:2;justify-content:flex-start}}
        @media(max-width:650px){.shell{display:block;padding-bottom:70px}.sidebar{position:fixed;z-index:5;bottom:0;left:0;right:0;height:64px;padding:7px 10px calc(7px + env(safe-area-inset-bottom));border-right:0;border-top:1px solid var(--line);display:block}.brand,.nav-label,.sidebar-bottom{display:none}.nav{height:100%;grid-template-columns:repeat(4,1fr);gap:3px}.nav a{justify-content:center;flex-direction:column;gap:0;padding:5px 2px;font-size:10px}.nav-icon{font-size:17px;line-height:1.35}.main{padding:20px 18px 34px}.topbar{margin-bottom:34px}.heading-row{align-items:flex-start;flex-direction:column;gap:8px;margin-bottom:23px}.count-label{padding:0}.stats{gap:8px}.stat{padding:13px}.stat-value{font-size:21px}.task-row{padding:15px 14px;gap:10px}.status{font-size:10px;padding:4px 7px}.detail-grid{grid-template-columns:1fr}.profile-card{padding:21px;gap:15px}.avatar{width:60px;height:60px;border-radius:19px}.profile-name{font-size:20px}.about-card{padding:23px}.footer{margin-top:30px}}
    </style>
</head>
<body>
<div class="shell">
    <aside class="sidebar">
        <a class="brand" href="<?= site_url('/') ?>"><span class="brand-mark">d</span><span><span class="brand-name">daymark</span><span class="brand-caption" style="display:block">a little more intentional</span></span></a>
        <p class="nav-label">Workspace</p>
        <nav class="nav" aria-label="Main navigation">
            <a class="<?= $activePage === 'home' ? 'active' : '' ?>" href="<?= site_url('/') ?>"><span class="nav-icon">◷</span><span>Today</span></a>
            <a class="<?= $activePage === 'tasks' ? 'active' : '' ?>" href="<?= site_url('tasks') ?>"><span class="nav-icon">☷</span><span>All tasks</span></a>
            <a class="<?= $activePage === 'profile' ? 'active' : '' ?>" href="<?= site_url('profile') ?>"><span class="nav-icon">◎</span><span>Profile</span></a>
            <a class="<?= $activePage === 'about' ? 'active' : '' ?>" href="<?= site_url('about') ?>"><span class="nav-icon">✳</span><span>About</span></a>
        </nav>
        <div class="sidebar-bottom"><strong>Make room for what matters.</strong>A simple place to keep your day in view.</div>
    </aside>
    <main class="main">
        <header class="topbar"><div class="crumb">Workspace <span style="padding:0 7px;color:#c3c4bd">/</span><b><?= esc($pageTitle) ?></b></div><div class="today-pill"><span class="today-dot"></span><?= esc(date('D, M j')) ?></div></header>
        <div class="content"><?= $this->renderSection('content') ?></div>
        <footer class="footer">Daymark <span style="padding:0 5px">·</span> a calmer way to plan your day</footer>
    </main>
</div>
</body>
</html>
